d = sys.stdin.read().split()
t = int(d[0])
B = 300
seen = {(1, 1)}
st = [(1, 1)]
while st:
    i, j = st.pop()
    for a in ((2 * i, j), (i, 2 * j), (i - j, j), (i, j - i)):
        if 1 <= a[0] <= B and 1 <= a[1] <= B and a not in seen:
            seen.add(a)
            st.append(a)
print('\n'.join('Yes' if (int(d[1 + 2 * i]), int(d[2 + 2 * i])) in seen else 'No' for i in range(t)))

